div.script:
document.addEventListener(
    "DOMContentLoaded",
    function () {

        const form =
            document.getElementById("lr_form");

        if (!form) {
            return;
        }


        // =========================================
        // DOCUMENTO DNI / CE
        // =========================================

        const tipoDocumento =
            document.getElementById(
                "tipo_documento"
            );

        const numeroDocumento =
            document.getElementById(
                "numero_documento"
            );

        const nombreConsumidor =
            document.getElementById(
                "nombre_consumidor"
            );

        const btnBuscar =
            document.getElementById(
                "btn_buscar_dni"
            );

        const documentStatus =
            document.getElementById(
                "lr_document_status"
            );

        const nameHelp =
            document.getElementById(
                "lr_name_help"
            );


        function statusMessage(
            type,
            message
        ) {

            documentStatus.className =
                "lr-document-status lr-" + type;

            documentStatus.textContent =
                message;

        }


        function configureDocumentType() {

            if (
                tipoDocumento.value === "dni"
            ) {

                numeroDocumento.maxLength = 8;

                numeroDocumento.inputMode =
                    "numeric";

                btnBuscar.style.display =
                    "inline-flex";

                nameHelp.textContent =
                    "Para DNI intentaremos completar automáticamente el nombre.";

            } else {

                numeroDocumento.maxLength = 30;

                numeroDocumento.inputMode =
                    "text";

                btnBuscar.style.display =
                    "none";

                nombreConsumidor.readOnly =
                    false;

                statusMessage(
                    "warning",
                    "Para Carné de Extranjería ingrese los datos manualmente."
                );

                nameHelp.textContent =
                    "Ingrese el nombre completo manualmente.";

            }

        }


        async function consultarDNI() {

            const dni =
                numeroDocumento.value
                    .trim();

            if (
                !/^\d{8}$/.test(dni)
            ) {

                statusMessage(
                    "warning",
                    "El DNI debe contener exactamente 8 dígitos."
                );

                nombreConsumidor.readOnly =
                    false;

                return;
            }


            statusMessage(
                "loading",
                "Consultando documento..."
            );


            btnBuscar.disabled = true;


            try {

                const response =
                    await fetch(
                        "/libro-de-reclamaciones/consultar-dni",
                        {
                            method: "POST",

                            headers: {
                                "Content-Type":
                                    "application/json"
                            },

                            body: JSON.stringify({
                                jsonrpc: "2.0",
                                method: "call",
                                params: {
                                    numero_documento:
                                        dni
                                },
                                id: Date.now()
                            })
                        }
                    );


                const payload =
                    await response.json();


                const result =
                    payload.result || {};


                if (result.ok) {

                    nombreConsumidor.value =
                        result.nombre || "";

                    nombreConsumidor.readOnly =
                        true;

                    statusMessage(
                        "success",
                        "Datos encontrados. El nombre fue cargado automáticamente."
                    );

                } else {

                    nombreConsumidor.readOnly =
                        false;

                    statusMessage(
                        "warning",
                        result.message ||
                        "No se encontraron datos. Puede ingresar el nombre manualmente."
                    );

                    nombreConsumidor.focus();

                }

            } catch (error) {

                nombreConsumidor.readOnly =
                    false;

                statusMessage(
                    "warning",
                    "No fue posible consultar el DNI. Puede continuar ingresando los datos manualmente."
                );

            } finally {

                btnBuscar.disabled = false;

            }

        }


        tipoDocumento.addEventListener(
            "change",
            function () {

                numeroDocumento.value = "";

                nombreConsumidor.value = "";

                nombreConsumidor.readOnly =
                    false;

                documentStatus.className =
                    "lr-document-status";

                configureDocumentType();

            }
        );


        btnBuscar.addEventListener(
            "click",
            consultarDNI
        );


        numeroDocumento.addEventListener(
            "input",
            function () {

                if (
                    tipoDocumento.value ===
                    "dni"
                ) {

                    this.value =
                        this.value.replace(
                            /\D/g,
                            ""
                        );

                    nombreConsumidor.readOnly =
                        false;

                }

            }
        );


        numeroDocumento.addEventListener(
            "blur",
            function () {

                if (
                    tipoDocumento.value ===
                    "dni" &&
                    this.value.length === 8
                ) {

                    consultarDNI();

                }

            }
        );


        configureDocumentType();


        // =========================================
        // MENOR DE EDAD
        // =========================================

        const menorCheck =
            document.getElementById(
                "es_menor_edad"
            );

        const minorBox =
            document.getElementById(
                "lr_minor_box"
            );

        const minorName =
            document.getElementById(
                "representante_menor_nombre"
            );


        function toggleMinor() {

            if (menorCheck.checked) {

                minorBox.style.display =
                    "block";

                minorName.required =
                    true;

            } else {

                minorBox.style.display =
                    "none";

                minorName.required =
                    false;

            }

        }


        menorCheck.addEventListener(
            "change",
            toggleMinor
        );

        toggleMinor();


        // =========================================
        // FIRMA
        // =========================================

        const canvas =
            document.getElementById(
                "lr_signature_canvas"
            );

        const signatureInput =
            document.getElementById(
                "firma_consumidor"
            );

        const clearSignature =
            document.getElementById(
                "btn_clear_signature"
            );

        const ctx =
            canvas.getContext("2d");

        let drawing = false;

        let hasSignature = false;


        function resizeCanvas() {

            const ratio =
                Math.max(
                    window.devicePixelRatio || 1,
                    1
                );

            const rect =
                canvas.getBoundingClientRect();

            canvas.width =
                rect.width * ratio;

            canvas.height =
                rect.height * ratio;

            ctx.setTransform(
                ratio,
                0,
                0,
                ratio,
                0,
                0
            );

            ctx.lineWidth = 2;

            ctx.lineCap =
                "round";

            ctx.lineJoin =
                "round";

            ctx.strokeStyle =
                "#101828";

        }


        function getPoint(event) {

            const rect =
                canvas.getBoundingClientRect();

            const source =
                event.touches
                    ? event.touches[0]
                    : event;

            return {
                x:
                    source.clientX -
                    rect.left,

                y:
                    source.clientY -
                    rect.top
            };

        }


        function startDrawing(event) {

            event.preventDefault();

            drawing = true;

            const point =
                getPoint(event);

            ctx.beginPath();

            ctx.moveTo(
                point.x,
                point.y
            );

        }


        function draw(event) {

            if (!drawing) {
                return;
            }

            event.preventDefault();

            const point =
                getPoint(event);

            ctx.lineTo(
                point.x,
                point.y
            );

            ctx.stroke();

            hasSignature = true;

        }


        function stopDrawing(event) {

            if (!drawing) {
                return;
            }

            if (event) {
                event.preventDefault();
            }

            drawing = false;

            ctx.closePath();

        }


        canvas.addEventListener(
            "mousedown",
            startDrawing
        );

        canvas.addEventListener(
            "mousemove",
            draw
        );

        window.addEventListener(
            "mouseup",
            stopDrawing
        );


        canvas.addEventListener(
            "touchstart",
            startDrawing,
            {passive: false}
        );

        canvas.addEventListener(
            "touchmove",
            draw,
            {passive: false}
        );

        canvas.addEventListener(
            "touchend",
            stopDrawing,
            {passive: false}
        );


        clearSignature.addEventListener(
            "click",
            function () {

                ctx.clearRect(
                    0,
                    0,
                    canvas.width,
                    canvas.height
                );

                hasSignature = false;

                signatureInput.value = "";

            }
        );


        resizeCanvas();

        window.addEventListener(
            "resize",
            function () {

                if (!hasSignature) {
                    resizeCanvas();
                }

            }
        );


        // =========================================
        // ARCHIVOS
        // =========================================

        const fileInput =
            document.getElementById(
                "attachment_ids"
            );

        const fileList =
            document.getElementById(
                "lr_file_list"
            );


        fileInput.addEventListener(
            "change",
            function () {

                fileList.innerHTML = "";

                const files =
                    Array.from(
                        fileInput.files
                    );

                files.forEach(
                    function (file) {

                        const item =
                            document.createElement(
                                "div"
                            );

                        item.className =
                            "small border rounded-3 px-3 py-2 mb-2 bg-white";

                        item.textContent =
                            file.name +
                            " · " +
                            (
                                file.size /
                                1024 /
                                1024
                            ).toFixed(2) +
                            " MB";

                        fileList.appendChild(
                            item
                        );

                    }
                );

            }
        );


        // =========================================
        // RESUMEN
        // =========================================

        const btnPrepare =
            document.getElementById(
                "btn_prepare_submit"
            );

        const btnFinal =
            document.getElementById(
                "btn_final_submit"
            );


        btnPrepare.addEventListener(
            "click",
            function () {

                if (
                    !form.reportValidity()
                ) {
                    return;
                }


                if (!hasSignature) {

                    alert(
                        "Debe registrar su firma antes de continuar."
                    );

                    canvas.scrollIntoView({
                        behavior: "smooth",
                        block: "center"
                    });

                    return;
                }


                signatureInput.value =
                    canvas.toDataURL(
                        "image/png"
                    );


                const selectedBien =
                    form.querySelector(
                        "input[name='tipo_bien']:checked"
                    );

                const selectedTipo =
                    form.querySelector(
                        "input[name='tipo_reclamacion']:checked"
                    );


                if (!selectedBien) {

                    alert(
                        "Seleccione Producto o Servicio."
                    );

                    return;
                }


                if (!selectedTipo) {

                    alert(
                        "Seleccione Reclamo o Queja."
                    );

                    return;
                }


                document.getElementById(
                    "summary_nombre"
                ).textContent =
                    nombreConsumidor.value;


                document.getElementById(
                    "summary_documento"
                ).textContent =
                    tipoDocumento.options[
                        tipoDocumento.selectedIndex
                    ].text +
                    " " +
                    numeroDocumento.value;


                document.getElementById(
                    "summary_bien"
                ).textContent =
                    selectedBien.value ===
                    "producto"
                        ? "Producto"
                        : "Servicio";


                document.getElementById(
                    "summary_tipo"
                ).textContent =
                    selectedTipo.value ===
                    "reclamo"
                        ? "Reclamo"
                        : "Queja";


                document.getElementById(
                    "summary_detalle"
                ).textContent =
                    form.elements[
                        "detalle"
                    ].value;


                document.getElementById(
                    "summary_pedido"
                ).textContent =
                    form.elements[
                        "pedido_consumidor"
                    ].value;


                const modal =
                    bootstrap.Modal.getOrCreateInstance(
                        document.getElementById(
                            "modalConfirmacion"
                        )
                    );

                modal.show();

            }
        );


        btnFinal.addEventListener(
            "click",
            function () {

                btnFinal.disabled = true;

                btnFinal.innerHTML =
                    ' Registrando...';


                signatureInput.value =
                    canvas.toDataURL(
                        "image/png"
                    );


                form.submit();

            }
        );

    }
);

div.style:
background:#fff;
border:1px solid #e4e7ec;
border-radius:24px;
padding:42px;
text-align:center;
box-shadow:0 16px 45px rgba(16,24,40,.08);

width:70px;
height:70px;
margin:0 auto 18px;
border-radius:50%;
background:#ecfdf3;
color:#067647;
display:flex;
align-items:center;
justify-content:center;
font-size:31px;

margin:28px 0;
background:#f8fafc;
border:1px solid #e4e7ec;
border-radius:17px;
padding:22px;

max-width:900px;
margin:auto;
background:#fff;
border:1px solid #ddd;
padding:36px;
border-radius:15px;
